:host {
  display: block;
  max-width: 1040px;
  margin: 0 auto;
  padding: 24px;
  text-align: center;
}

.seat-limit-info {
  margin: 8px auto 16px;
}

.screen-indicator {
  background: #444;
  color: #fff;
  text-align: center;
  letter-spacing: 4px;
  padding: 8px;
  border-radius: 4px;
  margin-bottom: 12px;
}

$label: 24px;
$seat: 30px;
$aisle: 64px;

.seat-map {
  display: inline-block;
}

.seat-row {
  display: grid;
  grid-template-columns: $label repeat(4, $seat) $aisle repeat(16, $seat) $aisle repeat(4, $seat) $label;
  align-items: center;
  gap: 3px;
  margin-bottom: 3px;
}

.row-label {
  text-align: center;
  font-size: 0.75rem;
  color: #666;
}

.aisle {
  display: block;
}

.seat,
