  height: 28px;
  border: none;
  border-radius: 4px;
  color: #fff;
  font-size: 0.7rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
}

.couch {
  font-size: 0.65rem;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin: 20px 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.swatch {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  display: inline-block;
}

.selected-seats {
  margin: 16px 0;
}

.actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 16px;
}

