  it('formats a show date as "<Weekday> <D> <Mon> <HH:mm>"', () => {
    expect(formatShowDate('2026-09-15', '16:00')).toBe('Tuesday 15 Sep 16:00');
  });

  it('validates ISO dates strictly', () => {
    expect(isValidIsoDate('2026-09-15')).toBe(true);
