const { chromium } = require('/tmp/pw-test/node_modules/playwright-core');

async function main() {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:4200/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/pw-test/01-movie-list.png', fullPage: true });
  console.log('movie-list html snippet:', (await page.content()).includes('movie-list'));
  console.log('day-picker present:', await page.locator('[data-testid="day-picker"]').count());
  console.log('movie-card count:', await page.locator('[data-testid="movie-card"]').count());
  console.log('movies-empty count:', await page.locator('[data-testid="movies-empty"]').count());
  console.log('movies-loading count:', await page.locator('[data-testid="movies-loading"]').count());
  console.log('movies-error count:', await page.locator('[data-testid="movies-error"]').count());

  console.log('console/page errors so far:', JSON.stringify(errors));

  await browser.close();
}

main().catch((e) => {
  console.error('DRIVER FAILED', e);
  process.exit(1);
});

