const { chromium } = require('/tmp/pw-test/node_modules/playwright-core');

async function main() {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('requestfailed', (r) => errors.push('requestfailed: ' + r.url() + ' ' + r.failure()?.errorText));

  // Navigate straight to a date with screenings via URL query param.
  await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle' });
  await page.waitForSelector('[data-testid="movie-card"]', { timeout: 5000 });
  const cardCount = await page.locator('[data-testid="movie-card"]').count();
  console.log('movie-card count on 2026-09-15:', cardCount);
  await page.screenshot({ path: '/tmp/pw-test/02-movies-2026-09-15.png', fullPage: true });

  const firstScreeningBtn = page.locator('[data-testid="screening-button"]').first();
  const screeningId = await firstScreeningBtn.getAttribute('data-screening-id');
  console.log('clicking screening id', screeningId);
  await firstScreeningBtn.click();
  await page.waitForURL(/\/screenings\/\d+\/seats/, { timeout: 5000 });
  await page.waitForSelector('[data-testid="seat-map"]');
  console.log('seat count:', await page.locator('[data-testid="seat"]').count());
  console.log('couch count:', await page.locator('[data-testid="couch"]').count());
  console.log('unavailable count:', await page.locator('[data-state="unavailable"]').count());
  await page.screenshot({ path: '/tmp/pw-test/03-seat-map.png', fullPage: true });

  // Select two available regular seats and one couch.
  const availableSeats = page.locator('[data-testid="seat"][data-state="available"]');
  await availableSeats.nth(0).click();
  await availableSeats.nth(1).click();
  const availableCouch = page.locator('[data-testid="couch"][data-state="available"]').first();
  await availableCouch.click();
  await page.waitForTimeout(200);
  console.log('selected-seats-count text:', await page.locator('[data-testid="selected-seats-count"]').textContent());
  await page.screenshot({ path: '/tmp/pw-test/04-seats-selected.png', fullPage: true });

  await page.locator('[data-testid="continue-button"]').click();
  await page.waitForURL(/\/screenings\/\d+\/summary/, { timeout: 5000 });
  console.log('summary items:', await page.locator('[data-testid="summary-item"]').count());
  console.log('summary total:', await page.locator('[data-testid="summary-total"]').textContent());
  await page.screenshot({ path: '/tmp/pw-test/05-summary.png', fullPage: true });

  await page.locator('[data-testid="confirm-button"]').click();
  await page.waitForURL(/\/screenings\/\d+\/checkout/, { timeout: 5000 });
  await page.screenshot({ path: '/tmp/pw-test/06-checkout-empty.png', fullPage: true });

  // Click pay with empty form to see validation errors.
  await page.locator('[data-testid="pay-button"]').click();
  await page.waitForTimeout(200);
  console.log('first-name-error:', await page.locator('[data-testid="first-name-error"]').textContent().catch(() => 'MISSING'));
  console.log('toast text:', await page.locator('[data-testid="toast"]').textContent().catch(() => 'MISSING'));
  await page.screenshot({ path: '/tmp/pw-test/07-checkout-errors.png', fullPage: true });

  // Fill the form correctly.
  await page.locator('[data-testid="first-name-input"]').fill('Anna');
  await page.locator('[data-testid="last-name-input"]').fill('Kowalska');
  await page.locator('[data-testid="email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="confirm-email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="phone-input"]').fill('123456789');
  await page.locator('[data-testid="terms-checkbox"]').click();
  await page.waitForTimeout(200);
  console.log('pay button text:', await page.locator('[data-testid="pay-button"]').textContent());
  await page.screenshot({ path: '/tmp/pw-test/08-checkout-filled.png', fullPage: true });

  await page.locator('[data-testid="pay-button"]').click();
  await page.waitForURL(/\/confirmation/, { timeout: 5000 });
  console.log('confirmation message:', await page.locator('[data-testid="confirmation-message"]').textContent());
  await page.screenshot({ path: '/tmp/pw-test/09-confirmation.png', fullPage: true });

  console.log('ALL ERRORS COLLECTED:', JSON.stringify(errors));

  await browser.close();
}

main().catch((e) => {
  console.error('DRIVER FAILED', e);
  process.exit(1);
});

