const { chromium } = require('/tmp/pw-test/node_modules/playwright-core');

async function main() {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage();
  page.on('console', (m) => console.log('CONSOLE', m.type(), m.text()));
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message, e.stack));
  page.on('crash', () => console.log('PAGE CRASHED'));
  page.on('close', () => console.log('PAGE CLOSED'));

  // Seed a valid booking with one seat directly in sessionStorage before the app boots.
  await page.goto('http://localhost:4200/');
  await page.evaluate(() => {
    sessionStorage.setItem(
      'cinescope-booking',
